<template><div class="page-container"><div class="page-header"><h2>合约管理</h2><el-button type="primary" @click="showForm=true">部署合约</el-button></div><el-table :data="contracts" border stripe><el-table-column prop="address" label="合约地址" min-width="250"><template #default="{r}"><span style="font-family:monospace;font-size:12px">{{r.address}}</span></template></el-table-column><el-table-column prop="name" label="名称"/><el-table-column prop="status" label="状态" width="80"><template #default="{r}"><el-tag :type="r.status==='active'?'success':'info'" size="small">{{r.status}}</el-tag></template></el-table-column></el-table><el-dialog v-model="showForm" title="部署合约" width="500px"><el-form :model="form" label-width="80px"><el-form-item label="合约名称"><el-input v-model="form.name"/></el-form-item></el-form><template #footer><el-button @click="showForm=false">取消</el-button><el-button type="primary" @click="deploy" :loading="deploying">部署</el-button></template></el-dialog></div></template>
<script setup>import {ref,reactive,onMounted} from 'vue';import {blockchainApi} from '@/api';import {ElMessage} from 'element-plus';const contracts=ref([]),showForm=ref(false),deploying=ref(false);const form=reactive({name:''});onMounted(async()=>{try{const r=await blockchainApi.getContractList();contracts.value=r.data||[]}catch(e){}});async function deploy(){deploying.value=true;try{const r=await blockchainApi.deployContract(form);ElMessage.success(`合约已部署: ${r.data.address.substring(0,20)}...`);showForm.value=false;const r2=await blockchainApi.getContractList();contracts.value=r2.data||[]}catch(e){}finally{deploying.value=false}}</script>
